import { completeExchange } from "./exchange";
import { parseFragment, providerErrorResult, type ManagedFragment } from "./fragment";
import { Pkce } from "./pkce";
import type { FlowContext, SignInOptions } from "./plugin";
import { applicationScheme } from "./scheme";
import { buildStartUrl } from "./start-url";

/**
 * The Electron renderer sign-in leg — `managedAuthClient` runs it when it detects the bridge.
 * Pure browser code — it only talks to the bridge the app's preload script exposes; the
 * Electron-touching halves live in desktop-main/desktop-preload.
 */

/** Renderer bridge to the Electron main process — built by `createManagedAuthBridge()` (`@runablehq/managed-auth/desktop/preload`) and exposed by the app's preload script. */
export interface DesktopBridge {
  /** Open the sign-in URL in the user's default browser (`shell.openExternal`). */
  openExternal(url: string): void | Promise<void>;
  /** Subscribe to OS deep-link URLs forwarded by the main process; returns unsubscribe. */
  onDeepLink(callback: (url: string) => void): () => void;
  /**
   * The deep-link target for this run: the dev loopback relay URL in unpackaged runs (macOS scheme
   * dispatch is unreliable there — every dev Electron shares one bundle id), undefined in packaged
   * builds, which use the registered scheme instead.
   */
  getRedirectTarget?(): Promise<string | undefined>;
}

/** The bridge at `window.managedAuth`, when this page runs inside an Electron shell wired for managed auth. */
export const getDesktopBridge = (): DesktopBridge | undefined =>
  (globalThis as { managedAuth?: DesktopBridge }).managedAuth;

export interface DesktopFlowConfig {
  /** `APPLICATION_ID` — identifies this app to the broker; the minted JWT's `aud` is bound to it. */
  applicationId: string;
  /** Broker base for THIS environment, e.g. `https://api.runable.com/api/auth`. */
  issuer: string;
  /**
   * Overrides deep-link target resolution entirely (bridge `getRedirectTarget`, then the
   * registered scheme). The broker's dev gate accepts `http://localhost:<port>/` targets.
   */
  redirectTarget?: string;
}

const DEEP_LINK_TIMEOUT_MS = 5 * 60 * 1000;

// Resolves with the matching fragment, or undefined on timeout. Deep links that don't parse or
// don't carry this attempt's nonce are other features' traffic — ignored, not errors.
const waitForDeepLink = (bridge: DesktopBridge, nonce: string) =>
  new Promise<ManagedFragment | undefined>((resolve) => {
    const settle = (fragment: ManagedFragment | undefined) => {
      unsubscribe();
      clearTimeout(timeout);
      resolve(fragment);
    };
    const unsubscribe = bridge.onDeepLink((url) => {
      const fragment = parseFragment(url);
      if (fragment && fragment.nonce === nonce) settle(fragment);
    });
    const timeout = setTimeout(() => settle(undefined), DEEP_LINK_TIMEOUT_MS);
  });

export interface DesktopFlowContext extends FlowContext {
  config: DesktopFlowConfig;
  bridge: DesktopBridge;
}

/** Opens the sign-in URL in the system browser and completes when the OS deep link (or dev relay callback) comes back over the bridge. */
export const desktopSignIn = async (
  { config, bridge, ...context }: DesktopFlowContext,
  options: SignInOptions,
) => {
  const nonce = Pkce.randomToken();
  // PKCE binds the fragment token to this window: another app registering the same protocol can
  // intercept the deep link, but cannot redeem the JWT without the verifier.
  const codeVerifier = Pkce.randomToken();
  // Default: the dev loopback relay when the main process runs one (unpackaged runs), otherwise
  // the platform-managed scheme it registered — the only targets the broker validates for this app.
  const redirectTarget =
    config.redirectTarget ??
    (await bridge.getRedirectTarget?.()) ??
    `${applicationScheme(config.applicationId)}://auth/callback`;
  const url = buildStartUrl({
    issuer: config.issuer,
    applicationId: config.applicationId,
    provider: options.provider,
    redirectTarget,
    nonce,
    codeChallenge: await Pkce.challengeS256(codeVerifier),
  });

  await bridge.openExternal(url);
  const fragment = await waitForDeepLink(bridge, nonce);
  if (!fragment) {
    return { data: null, error: { code: "DEEP_LINK_TIMEOUT", message: "Sign-in timed out" } };
  }
  if ("error" in fragment) return providerErrorResult(fragment);
  return completeExchange(context, { token: fragment.token, codeVerifier });
};
